const OLD_TRAITS = { j: ['oldj', 'simple'], m: ['oldm', 'tapered', 'retro'], c: ['oldc', 'airy'], i: ['oldi', 'blackmetal', 'raw'], b: ['oldb', 'earthy'] };

function traitsFor(name, cat, extra, oldLetter) {
  const n = name.toLowerCase(), t = new Set(extra ? extra.split(/\s+/).filter(Boolean) : []);
  for (const [k, rx] of TRAIT_RX) if (rx.test(n)) t.add(k);
  if (cat === 'plant') t.add('plant');
  if (oldLetter && OLD_TRAITS[oldLetter]) OLD_TRAITS[oldLetter].forEach(x => t.add(x));
  const has = k => t.has(k);
  if (['floral', 'stripe', 'geometric', 'medallion', 'southwestern', 'multicolor'].some(has) || /marbled|butterfl/.test(n)) t.add('pattern');
  if (['rolledarm', 'wing', 'carved', 'medallion', 'tufted', 'pedestal', 'nailhead'].some(has)) t.add('traditional');
  if (/weathered|reclaimed|distressed|salvaged|antique|live edge/.test(n) || has('pine') || has('jute')) t.add('rustic');
  if (['rattan', 'jute', 'terracotta', 'stone', 'warmwood', 'bamboo'].some(has)) t.add('earthy');
  if (!['pattern', 'tufted', 'carved', 'sculptural', 'traditional'].some(has)) t.add('simple');
  if (has('navy')) t.add('blue');
  if (['black', 'navy', 'darkwood'].some(has) || /charcoal|dark gray|dark blue|dark green|fir green|forest green|dark brown|anthracite/.test(n)) t.add('dark');
  if (['white', 'cream', 'lightwood'].some(has) || /pale|light /.test(n)) t.add('light');
  return t;
}
